6	// ---------------------------------------------------------------------------
7	
8	const CORS_HEADERS = {
9	  "Access-Control-Allow-Origin": "*",
10	  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
11	  "Access-Control-Allow-Headers": "Content-Type",
12	};
13	
14	// ---------------------------------------------------------------------------
15	// Validation
16	// ---------------------------------------------------------------------------
17	
18	const SHOP_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
19	
20	const VALID_EVENT_TYPES = [
21	  "view",
22	  "click",
23	  "recommend",
24	  "convert",
25	  "dismiss",
26	] as const;
27	
28	type EventType = (typeof VALID_EVENT_TYPES)[number];
29	
30	interface AnalyticsEventBody {
31	  shop: string;
32	  eventType: EventType;
33	  sizeChartId?: string;
34	  productId?: string;
35	  metadata?: Record<string, unknown>;
36	}
37	
38	// ---------------------------------------------------------------------------
39	// Preflight
40	// ---------------------------------------------------------------------------
41	
42	export const loader = async ({ request }: LoaderFunctionArgs) => {
43	  if (request.method === "OPTIONS") {
44	    return new Response(null, { status: 204, headers: CORS_HEADERS });
45	  }
46	  return Response.json(
47	    { error: "Method not allowed" },
48	    { status: 405, headers: CORS_HEADERS },
49	  );
50	};
