52	// ---------------------------------------------------------------------------
53	// Action — POST /api/analytics-event
54	// Body JSON: { shop, eventType, sizeChartId?, productId?, metadata? }
55	// ---------------------------------------------------------------------------
56	
57	export const action = async ({ request }: ActionFunctionArgs) => {
58	  if (request.method === "OPTIONS") {
59	    return new Response(null, { status: 204, headers: CORS_HEADERS });
60	  }
61	
62	  if (request.method !== "POST") {
63	    return Response.json(
64	      { error: "Method not allowed" },
65	      { status: 405, headers: CORS_HEADERS },
66	    );
67	  }
68	
69	  let body: Partial<AnalyticsEventBody>;
70	
71	  try {
72	    body = (await request.json()) as Partial<AnalyticsEventBody>;
73	  } catch {
74	    return Response.json(
75	      { error: "Invalid JSON body" },
76	      { status: 400, headers: CORS_HEADERS },
77	    );
78	  }
79	
80	  const { shop, eventType, sizeChartId, productId, metadata } = body;
81	
82	  // Validate shop
83	  if (!shop || !SHOP_RE.test(shop)) {
84	    return Response.json(
85	      { error: "Invalid or missing shop parameter" },
86	      { status: 400, headers: CORS_HEADERS },
87	    );
88	  }
89	
90	  // Validate eventType
91	  if (
92	    !eventType ||
93	    !(VALID_EVENT_TYPES as readonly string[]).includes(eventType)
94	  ) {
95	    return Response.json(
96	      {
97	        error: `eventType must be one of: ${VALID_EVENT_TYPES.join(", ")}`,
98	      },
99	      { status: 400, headers: CORS_HEADERS },
100	    );
101	  }
102	
103	  // Validate optional ID formats to prevent DB pollution
104	  const PRODUCT_ID_RE = /^(\d{1,20}|gid:\/\/shopify\/Product\/\d{1,20})$/;
105	  const CHART_ID_RE = /^[a-z0-9]{1,30}$/;
106	
107	  if (productId !== undefined && productId !== null && !PRODUCT_ID_RE.test(productId)) {
108	    return Response.json(
109	      { error: "Invalid productId format" },
110	      { status: 400, headers: CORS_HEADERS },
111	    );
112	  }
113	  if (sizeChartId !== undefined && sizeChartId !== null && !CHART_ID_RE.test(sizeChartId)) {
114	    return Response.json(
115	      { error: "Invalid sizeChartId format" },
116	      { status: 400, headers: CORS_HEADERS },
117	    );
118	  }
119	
120	  // Fire-and-forget: respond immediately and write in the background
121	  // We still await to keep error handling consistent, but we return fast
122	  // because DB writes are non-blocking in practice at this scale
123	  try {
124	    const metadataRaw =
125	      metadata !== undefined && metadata !== null
126	        ? JSON.stringify(metadata)
127	        : "{}";
128	    // Clamp metadata size to prevent storage abuse
129	    const metadataJson = metadataRaw.length > 2048 ? "{}" : metadataRaw;
130	
131	    await db.analyticsEvent.create({
132	      data: {
133	        shop,
134	        eventType,
135	        sizeChartId: sizeChartId ?? null,
136	        productId: productId ?? null,
137	        metadata: metadataJson,
138	      },
139	    });
140	
141	    return Response.json({ ok: true }, { headers: CORS_HEADERS });
142	  } catch {
143	    // Non-critical: tracking failures should not break the storefront
144	    // Still return 200 to avoid retries from the widget
145	    return Response.json({ ok: true }, { headers: CORS_HEADERS });
146	  }
147	};
