291	
292	  try {
293	    body = (await request.json()) as Partial<RecommendRequestBody>;
294	  } catch {
295	    return Response.json(
296	      { error: "Invalid JSON body" },
297	      { status: 400, headers: CORS_HEADERS },
298	    );
299	  }
300	
301	  const { shop, chartId, height, weight, unit, gender, bodyType } = body;
302	
303	  // Validate shop
304	  if (!shop || !SHOP_RE.test(shop)) {
305	    return Response.json(
306	      { error: "Invalid or missing shop parameter" },
307	      { status: 400, headers: CORS_HEADERS },
308	    );
309	  }
310	
311	  // Validate required fields
312	  if (!chartId) {
313	    return Response.json(
314	      { error: "chartId is required" },
315	      { status: 400, headers: CORS_HEADERS },
316	    );
317	  }
318	  if (typeof height !== "number" || height <= 0) {
319	    return Response.json(
320	      { error: "height must be a positive number" },
321	      { status: 400, headers: CORS_HEADERS },
322	    );
323	  }
324	  if (typeof weight !== "number" || weight <= 0) {
325	    return Response.json(
326	      { error: "weight must be a positive number" },
327	      { status: 400, headers: CORS_HEADERS },
328	    );
329	  }
